import numpy as np
import time

import util_plan
import util_consts

from util_io import read_arguments, read_trajectories, import_module
from util_dpu import capture


def main():

    # --! read arguments with extra export-specific arguments and options; no base arguments and options
    args = {
        'pipeline': {
            'help'    : "numpy port of model's forward method"
        },
        'plan': {
            'help'    : 'model_plan.json produced by analyze_model.py'
        },
        'consts': {
            'help'    : 'model_consts.json generated by export_constants.py'
        },
    }
    options = {
        '--xmodels': {
            'help'    : 'directory with <stage>.xmodel files',
            'default' : '.'
        },
        '--data': {
            'help'    : '.csv with raw trajectories (rows=time, columns=channels)'
        },
        '--traj-nsample': {
            'type'    : int,
            'help'    : 'number of rows per trajectory in --data'
        },
        '--labels': {
            'help'    : '.csv file with one label per raw sample, same row layout as --data'
        },
        '--out-field': {
            'help'    : 'field of pipeline output to evaluate',
            'default' : 'score'
        },
        '--golden': {
            'help'    : 'golden.npz obtained from check_pipeline.py'
        }
    }
    ns = read_arguments(
        description='run a whole bridge model: dpu stages plus numpy glue',
        base_used=False,
        extra_args=args, extra_options=options)

    # --! impose extra constraints on them at run time
    if not ns.data or not ns.traj_nsample:
        raise SystemExit('[error]: for pipeline running, --data and --traj-nsample are required')

    # --! load model plan and constants
    plan, consts = util_plan.load(ns.plan), util_consts.load(ns.consts)

    # --! construct dpu stages based on model plan and xmodels
    stages = plan.to_dpus(ns.xmodels)

    for name, (i, o) in plan.get_stage_rows().items():
        print(f'[note]: stage {name}: rows {i} -> {o}')

    # --! import pipeline module, model's forward method ported to numpy
    pipe = import_module(ns.pipeline, 'pipeline', ['make_inputs', 'run'])

    data = read_trajectories(ns.data, ns.traj_nsample)
    print(f'[note]: read {data.shape[0]} trajectories of shape {data.shape[1:]} from {ns.data}')

    labels = None
    if ns.labels:
        if not hasattr(pipe, 'align_labels'):
            raise SystemExit(f'[error]: --labels needs align_labels(labels, c) in {ns.pipeline}')
        labels = read_trajectories(ns.labels, ns.traj_nsample)

        if labels.shape[2] != 1:
            raise SystemExit(f'[error]: {ns.labels} must have exactly one column')

        labels = labels[:, :, 0].astype(np.int64)

    nrow = ncorrect = 0
    seconds = 0.0
    first_out = None
    for t in range(data.shape[0]):
        # --! on trajectory 0, record what flows through the stages, for the comparison with the host golden
        stages_t = stages
        if t == 0:
            store = {}
            stages_t = {name: capture(name, st, store) for name, st in stages.items()}

        t0 = time.perf_counter()
        out = pipe.run(pipe.make_inputs(data[t], consts), stages_t, consts)
        seconds += time.perf_counter() - t0

        score = getattr(out, ns.out_field)
        pred = np.argmax(score, axis=-1)
        nrow += pred.shape[0]
        if labels is not None:
            ncorrect += int((pred == pipe.align_labels(labels[t], consts)).sum())
        if t == 0:
            first_out = out
        print(f'[note]: trajectory {t + 1}/{data.shape[0]} done')

    print('')
    print(f'[result]: {data.shape[0]} trajectories, {nrow} classified rows')
    if labels is not None:
        print('[result]: on-target accuracy : %.2f%%' % (100.0 * ncorrect / nrow))
    print('[result]: %.3f s per trajectory (%.3f ms per row, glue included)'
          % (seconds / data.shape[0], 1000.0 * seconds / nrow))

    if ns.golden:

        # --! every field of the golden file is compared, in pipeline order, so the
        # --! first field that differs shows where the board departs from the host
        gold = np.load(ns.golden)
        print('[result]: trajectory 0 against the host (numpy glue + fake-quantized stages)')
        for field in gold.files:
            if not hasattr(first_out, field):
                continue
            got, ref = np.asarray(getattr(first_out, field)), gold[field]
            if got.shape != ref.shape:
                print(f'[result]:   {field:<6} shape {got.shape}, golden has {ref.shape}')
                continue
            d = np.abs(got - ref)
            print('[result]:   %-6s identical %6.2f%%   within 1e-3 %6.2f%%   max |difference| %.4g'
                  % (field, 100.0 * np.mean(d < 1e-6), 100.0 * np.mean(d <= 1e-3), d.max()))

        ref = gold[ns.out_field]
        got = np.asarray(getattr(first_out, ns.out_field))
        if got.shape == ref.shape:
            print('[result]:   %s argmax agreement %.2f%%'
                  % (ns.out_field, 100.0 * np.mean(np.argmax(got, -1) == np.argmax(ref, -1))))

        # --! step by step: the first line that differs is where the board departs from the host
        def compare(label, got, ref):
            got, ref = np.asarray(got), np.asarray(ref)
            if got.shape != ref.shape:
                print(f'[result]:   {label:<36} shape {got.shape}, golden has {ref.shape}')
            else:
                d = np.abs(got - ref)
                print('[result]:   %-36s identical %6.2f%%   max |difference| %.4g'
                      % (label, 100.0 * np.mean(d < 1e-6), d.max()))

        print('[result]: trajectory 0, step by step')
        if 'raw_trajectory' in gold.files:
            compare('raw trajectory', data[0], gold['raw_trajectory'])
        if 'raw_windows' in gold.files:
            compare('raw windows (make_inputs)', pipe.make_inputs(data[0], consts), gold['raw_windows'])
        for name, st in stages.items():
            if f'in_{name}' in gold.files:
                compare(f'stage {name}: input rows', store[f'in_{name}'], gold[f'in_{name}'])
                compare(f'stage {name}: output, host rows in', st(gold[f'in_{name}']), gold[f'out_{name}'])


if __name__ == '__main__':
    main()

